bool GCSplitItemResult::read(Reader& r) {
    if (!r.i16(this->con_index)) return r.fail("short read", "GCSplitItemResult.con_index");
    if (!r.u32(this->is_null)) return r.fail("short read", "GCSplitItemResult.is_null");
    if (!r.u32(this->container)) return r.fail("short read", "GCSplitItemResult.container");
    if (!r.u8(this->result)) return r.fail("short read", "GCSplitItemResult.result");
    if (!this->item.read(r)) return false;
    return true;
}

void GCSplitItemResult::write(Writer& w) const {
    w.i16(this->con_index);
    w.u32(this->is_null);
    w.u32(this->container);
    w.u8(this->result);
    this->item.write(w);
}

bool CGPackUpPacket::read(Reader& r) {
    if (!r.u32(this->unknow)) return r.fail("short read", "CGPackUpPacket.unknow");
    return true;
}

void CGPackUpPacket::write(Writer& w) const {
    w.u32(this->unknow);
}

